// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.security.MessageDigest;
import java.util.HexFormat;
import java.util.Map;
import java.util.TreeMap;

import org.eclipse.rdf4j.model.Literal;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.sail.SailException;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class ValueStoreDictionaryOwnershipTest {

	@TempDir
	Path directory;

	@Test
	void bareFreshOwnerPersistsCompleteCapabilitiesForColdReopen() throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig().setInlineLiterals(false).setOrderedNumericIds(true);
		Literal literal = SimpleValueFactory.getInstance().createLiteral("owned current dictionary literal");
		long id;
		ValueStore first = new ValueStore(directory.toFile(), config);
		try {
			id = first.storeValue(literal);
		} finally {
			first.close();
		}
		StoreProperties persisted = new StoreProperties(directory.toFile());
		assertThat(persisted.load()).as("the dictionary owner persists its actual encoding identity").isTrue();
		assertThat(persisted.getVersion()).isEqualTo(Integer.toString(LmdbStoreFormat.CURRENT_VERSION));
		assertThat(persisted.usesCoreDatatypeLiteralReferences()).isTrue();
		assertThat(persisted.usesCanonicalLanguageTags()).isTrue();
		assertThat(persisted.usesZeroFractionDateTimeIds()).isTrue();
		assertThat(persisted.usesOrderedNumericIds()).isTrue();
		ValueStore reopened = new ValueStore(directory.toFile(), config);
		try {
			assertThat(reopened.getId(literal, false)).isEqualTo(id);
			assertThat(reopened.getValue(id)).isEqualTo(literal);
		} finally {
			reopened.close();
		}
	}

	@Test
	void loadedLegacyOwnerKeepsItsOriginalSpellingAndFormat() throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig().setInlineLiterals(false);
		StoreProperties properties = new StoreProperties(directory.toFile());
		properties.setVersion(Integer.toString(LmdbStoreFormat.LEGACY_VERSION));
		properties.setLanguageTagKey(StoreProperties.LANGUAGE_TAG_KEY_BYTE_EXACT);
		Literal literal = SimpleValueFactory.getInstance().createLiteral("legacy spelling", "eN");
		ValueStore initial = new ValueStore(directory.toFile(), properties, config);
		long id;
		try {
			id = initial.storeValue(literal);
		} finally {
			initial.close();
		}
		properties.save();
		ValueStore reopened = new ValueStore(directory.toFile(), config);
		try {
			assertThat(reopened.getFormat().isLegacy()).isTrue();
			assertThat(reopened.getFormat().usesCoreDatatypeLiteralReferences()).isFalse();
			assertThat(reopened.getId(literal, false)).isEqualTo(id);
			assertThat(((Literal) reopened.getValue(id)).getLanguage()).isEqualTo(literal.getLanguage());
		} finally {
			reopened.close();
		}
	}

	@Test
	void incompatibleInlineSettingIsRejectedBeforeNativeMutation() throws Exception {
		writeExplicitCurrentDictionary();
		Map<String, String> before = fileHashes();
		assertThatThrownBy(
				() -> new ValueStore(directory.toFile(), new LmdbStoreConfig().setInlineLiterals(true)).close())
						.isInstanceOf(SailException.class)
						.hasMessageContaining("must be opened with its original setting");
		assertThat(fileHashes()).isEqualTo(before);
	}

	@Test
	void existingDictionaryWithoutCapabilitiesIsRejectedBeforeNativeMutation() throws Exception {
		writeExplicitCurrentDictionary();
		Files.delete(directory.resolve(StoreProperties.FILE_NAME));
		Map<String, String> before = fileHashes();
		assertThatThrownBy(
				() -> new ValueStore(directory.toFile(), new LmdbStoreConfig().setInlineLiterals(false)).close())
						.isInstanceOf(IOException.class)
						.hasMessageContaining("Missing store.properties in a nonempty ValueStore dictionary directory");
		assertThat(fileHashes()).isEqualTo(before);
	}

	@Test
	void explicitlySuppliedTransientLegacyCodecSeamDoesNotBecomeCurrent() throws Exception {
		StoreProperties properties = new StoreProperties();
		properties.setVersion(Integer.toString(LmdbStoreFormat.LEGACY_VERSION));
		properties.setLanguageTagKey(StoreProperties.LANGUAGE_TAG_KEY_BYTE_EXACT);
		ValueStore values = new ValueStore(directory.toFile(), properties, new LmdbStoreConfig());
		try {
			assertThat(values.getFormat().isLegacy()).isTrue();
			assertThat(values.getFormat().usesCoreDatatypeLiteralReferences()).isFalse();
			assertThat(values.getFormat().usesCanonicalLanguageTags()).isFalse();
			assertThat(values.getFormat().usesZeroFractionDateTimeIds()).isFalse();
		} finally {
			values.close();
		}
		assertThat(directory.resolve(StoreProperties.FILE_NAME)).doesNotExist();
	}

	private void writeExplicitCurrentDictionary() throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig().setInlineLiterals(false);
		StoreProperties properties = new StoreProperties(directory.toFile());
		LmdbStoreFormat format = LmdbStoreFormat.forNewStore(config);
		format.initializeProperties(properties);
		ValueStore values = new ValueStore(directory.toFile(), properties, config, false, null, format, false);
		try {
			values.storeValue(SimpleValueFactory.getInstance().createLiteral("preserve this actual native owner"));
		} finally {
			values.close();
		}
		properties.save();
	}

	private Map<String, String> fileHashes() throws Exception {
		Map<String, String> hashes = new TreeMap<>();
		try (var files = Files.walk(directory)) {
			for (Path file : files.filter(Files::isRegularFile).toList()) {
				hashes.put(directory.relativize(file).toString(), HexFormat.of()
						.formatHex(
								MessageDigest.getInstance("SHA-256").digest(Files.readAllBytes(file))));
			}
		}
		return hashes;
	}
}
